    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr\">(Δ) ⊥ (AB)</span>  و  <span dir=\"ltr\" class=\"expr pt\">M</span> هو منتصف القطعة <span dir=\"ltr\" class=\"expr\">[AB]</span>"},{"quoi":"الاختيار","math":"المطلوب : إثبات أنّ <span dir=\"ltr\" class=\"expr\">(Δ)</span> هو الموسط العمودي. نختار العمودي المارّ من المنتصف لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr\">: (Δ) ⊥ (AB)</span>  و  <span dir=\"ltr\" class=\"expr pt\">M</span> هو منتصف القطعة <span dir=\"ltr\" class=\"expr\">[AB]</span>  و  <span dir=\"ltr\" class=\"expr\">M ∈ (Δ).</span> و لماذا لا عموديان على نفس المستقيم ؟ لأنّها تحتاج مستقيمين عموديين على نفس المستقيم، و لا نملك إلّا تعامدا واحدا على الأكثر."},{"quoi":"القاعدة","math":"المستقيم العمودي على قطعة و المارّ من منتصفها هو موسطها العمودي"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr\">(Δ) ⊥ (AB)</span>  و  <span dir=\"ltr\" class=\"expr pt\">M</span> هو منتصف القطعة <span dir=\"ltr\" class=\"expr\">[AB]</span>  و  <span dir=\"ltr\" class=\"expr\">M ∈ (Δ)</span>  إذن  <span dir=\"ltr\" class=\"expr\">(Δ)</span> هو الموسط العمودي للقطعة <span dir=\"ltr\" class=\"expr\">[AB]</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">(Δ)</span> هو الموسط العمودي للقطعة <span dir=\"ltr\" class=\"expr\">[AB]</span>"}],
