    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr\">(BA) // (IE)</span>  و  <span dir=\"ltr\" class=\"expr\">(AI) // (EB)</span>  و  <span dir=\"ltr\" class=\"expr\">(BA) ⊥ (EB)</span>"},{"quoi":"نفس المستقيم","math":"<span dir=\"ltr\" class=\"expr\">(BA)</span> و <span dir=\"ltr\" class=\"expr\">(BU)</span> هما نفس المستقيم"},{"quoi":"نفس المستقيم","math":"<span dir=\"ltr\" class=\"expr\">(EB)</span> و <span dir=\"ltr\" class=\"expr\">(BT)</span> هما نفس المستقيم"},{"quoi":"الاختيار","math":"المطلوب : تعيين طبيعة الرباعي <span dir=\"ltr\" class=\"expr\">BAIE.</span> نختار متوازي الأضلاع لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr\">: (BA) // (IE)</span>  و  <span dir=\"ltr\" class=\"expr\">(AI) // (EB).</span> و لماذا لا عموديان على نفس المستقيم ؟ لأنّها تحتاج مستقيمين عموديين على نفس المستقيم، و لا نملك إلّا تعامدا واحدا على الأكثر."},{"quoi":"القاعدة","math":"الرباعي الذي أضلاعه متوازية مثنى مثنى هو متوازي أضلاع"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr\">(BA) // (IE)</span>  و  <span dir=\"ltr\" class=\"expr\">(AI) // (EB)</span>  إذن  الرباعي <span dir=\"ltr\" class=\"expr\">BAIE</span> هو متوازي أضلاع"},{"quoi":"القاعدة","math":"متوازي أضلاع له زاوية قائمة هو مستطيل"},{"quoi":"نطبّق","math":"الرباعي <span dir=\"ltr\" class=\"expr\">BAIE</span> هو متوازي أضلاع  و  <span dir=\"ltr\" class=\"expr\">(BA) ⊥ (EB)</span>  إذن  الرباعي <span dir=\"ltr\" class=\"expr\">BAIE</span> هو مستطيل"},{"quoi":"النتيجة","math":"الرباعي <span dir=\"ltr\" class=\"expr\">BAIE</span> هو مستطيل"}],
