    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr\">(d1)</span> هو الموسط العمودي للقطعة <span dir=\"ltr\" class=\"expr\">[AB]</span>  و  <span dir=\"ltr\" class=\"expr\">(d2)</span> هو الموسط العمودي للقطعة <span dir=\"ltr\" class=\"expr\">[AC]</span>"},{"quoi":"الاختيار","math":"المطلوب : إثبات تساوي الطولين. نختار نقطة من الموسط العمودي لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr\">: (d1)</span> هو الموسط العمودي للقطعة <span dir=\"ltr\" class=\"expr\">[AB]</span>  و  <span dir=\"ltr\" class=\"expr\">M ∈ (d1).</span> و لماذا لا عموديان على نفس المستقيم ؟ لأنّها تحتاج مستقيمين عموديين على نفس المستقيم، و لا نملك إلّا تعامدا واحدا على الأكثر."},{"quoi":"القاعدة","math":"كلّ نقطة من الموسط العمودي لقطعة متساوية البعد عن طرفيها"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr\">(d1)</span> هو الموسط العمودي للقطعة <span dir=\"ltr\" class=\"expr\">[AB]</span>  و  <span dir=\"ltr\" class=\"expr\">M ∈ (d1)</span>  إذن  <span dir=\"ltr\" class=\"expr\">MA = MB</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr\">(d2)</span> هو الموسط العمودي للقطعة <span dir=\"ltr\" class=\"expr\">[AC]</span>  و  <span dir=\"ltr\" class=\"expr\">M ∈ (d2)</span>  إذن  <span dir=\"ltr\" class=\"expr\">MA = MC</span>"},{"quoi":"القاعدة","math":"إذا كان طولان يساويان طولا ثالثا فهما متساويان"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr\">MB = MA</span>  و  <span dir=\"ltr\" class=\"expr\">MA = MC</span>  إذن  <span dir=\"ltr\" class=\"expr\">MB = MC</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">MB = MC</span>"}],
