    enonce: "<span dir=\"ltr\" class=\"expr\">ABC</span> مثلّث متقايس الضلعين قمته الرئيسية <span dir=\"ltr\" class=\"expr pt\">A</span>، حيث <span dir=\"ltr\" class=\"expr\">BC = 8.</span><br><span dir=\"ltr\" class=\"expr pt\">I</span> منتصف القطعة <span dir=\"ltr\" class=\"expr\">[BC].</span><br><svg class=\"figure\" direction=\"ltr\" viewBox=\"0 0 292 244\" width=\"292\" height=\"244\" xmlns=\"http://www.w3.org/2000/svg\"><line x1=\"92.0\" y1=\"50.0\" x2=\"50.0\" y2=\"194.0\" stroke=\"#2c3e50\" stroke-width=\"1.8\"/><line x1=\"92.0\" y1=\"50.0\" x2=\"242.0\" y2=\"50.0\" stroke=\"#2c3e50\" stroke-width=\"1.8\"/><line x1=\"50.0\" y1=\"194.0\" x2=\"242.0\" y2=\"50.0\" stroke=\"#2c3e50\" stroke-width=\"1.8\"/><line x1=\"92.0\" y1=\"50.0\" x2=\"146.0\" y2=\"122.0\" stroke=\"#2c3e50\" stroke-width=\"1.8\"/><path d=\"M 137.2 128.6 L 130.6 119.8 L 139.4 113.2\" fill=\"none\" stroke=\"#c0392b\" stroke-width=\"1.3\"/><line x1=\"95.0\" y1=\"154.0\" x2=\"101.0\" y2=\"162.0\" stroke=\"#c0392b\" stroke-width=\"1.3\"/><line x1=\"191.0\" y1=\"82.0\" x2=\"197.0\" y2=\"90.0\" stroke=\"#c0392b\" stroke-width=\"1.3\"/><circle cx=\"50.0\" cy=\"194.0\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"41.2\" y=\"207.6\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">B</text><circle cx=\"242.0\" cy=\"50.0\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"253.7\" y=\"48.3\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">C</text><circle cx=\"146.0\" cy=\"122.0\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"153.8\" y=\"136.4\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">I</text><circle cx=\"92.0\" cy=\"50.0\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"84.2\" y=\"43.6\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">A</text></svg><br>برهن أنّ<span dir=\"ltr\" class=\"expr\">: (AI)</span> هو الموسط العمودي للقطعة <span dir=\"ltr\" class=\"expr\">[BC]</span>",
    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr\">AB = AC</span>  و  <span dir=\"ltr\" class=\"expr pt\">I</span> هو منتصف القطعة <span dir=\"ltr\" class=\"expr\">[BC]</span>"},{"quoi":"الاختيار","math":"المطلوب : إثبات أنّ <span dir=\"ltr\" class=\"expr\">(AI)</span> هو الموسط العمودي. نختار المنتصف متساوي البعد لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr\">: I</span> هو منتصف القطعة <span dir=\"ltr\" class=\"expr\">[BC].</span> و لماذا لا عموديان على نفس المستقيم ؟ لأنّها تحتاج مستقيمين عموديين على نفس المستقيم، و لا نملك إلّا تعامدا واحدا على الأكثر."},{"quoi":"القاعدة","math":"منتصف قطعة متساوي البعد عن طرفيها"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">I</span> هو منتصف القطعة <span dir=\"ltr\" class=\"expr\">[BC]</span>  إذن  <span dir=\"ltr\" class=\"expr\">IB = IC</span>"},{"quoi":"القاعدة","math":"المستقيم المارّ من نقطتين متساويتي البعد عن طرفي قطعة هو موسطها العمودي"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr\">AB = AC</span>  و  <span dir=\"ltr\" class=\"expr\">A ∈ (AI)</span>  و  <span dir=\"ltr\" class=\"expr\">IB = IC</span>  و  <span dir=\"ltr\" class=\"expr\">I ∈ (AI)</span>  إذن  <span dir=\"ltr\" class=\"expr\">(AI)</span> هو الموسط العمودي للقطعة <span dir=\"ltr\" class=\"expr\">[BC]</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">(AI)</span> هو الموسط العمودي للقطعة <span dir=\"ltr\" class=\"expr\">[BC]</span>"}],
    indice: "نقطتان متساويتا البعد عن B و C تكفيان لتحديد الموسط العمودي",
